// === Tab: mySketch ===
let particles = [];

function setup() {
  createCanvas(4*windowHeight/3, windowHeight);
	colorMode(HSB, 255);
  background(0);
	window.simulatedMouseX = -1000;
	window.simulatedMouseY = -1000;
}

function draw() {
  background(0, 5); // Slowly fade out the background

  // Create new particles
  for (let i = 0; i < 5; i++) {
    particles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), random(255), 255, 255));
  }

  // Update and display particles
  for (let i = particles.length-1; i >= 0; i--) {
    let p = particles[i];
    p.update();
    p.display();
    if (p.isDead()) {
      // Remove dead particles
      particles.splice(i, 1);
    }
  }
}

class Particle {
  constructor(x, y, r, g, b) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D();
    this.vel.mult(random(2, 5)); // Set initial velocity
    this.alpha = 255;
    this.r = r;
    this.g = g;
    this.b = b;
  }

  update() {
    this.alpha -= 2; // Fade out over time
    this.pos.add(this.vel);
  }

  display() {
    noStroke();
    fill(this.r, this.g, this.b, this.alpha);
    ellipse(this.pos.x, this.pos.y, 10, 10);
  }

  isDead() {
    return this.alpha < 0;
  }
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

